15	    private static int findTargetIndex(final int[] values, final int target) {
16	        final SearchRange range = SearchRange.forSize(values.length);
17	
18	        while (range.hasCandidates()) {
19	            final int mid = range.midpoint();
20	            final int current = values[mid];
21	            final int comparison = Integer.compare(current, target);
22	
23	            if (comparison == 0) {
24	                return mid;
25	            }
26	
27	            if (comparison < 0) {
28	                range.discardLeftThrough(mid);
29	            } else {
30	                range.discardRightFrom(mid);
31	            }
32	        }
33	
34	        return NOT_FOUND;
35	    }
