51	    private static final class SearchRange {
52	        private int left;
53	        private int right;
54	
55	        private static SearchRange forSize(final int size) {
56	            return new SearchRange(0, size - 1);
57	        }
58	
59	        private SearchRange(final int left, final int right) {
60	            this.left = left;
61	            this.right = right;
62	        }
63	
64	        private boolean hasCandidates() {
65	            return left <= right;
66	        }
67	
